window.ScripturaLexicons.BDAG_PART_0203 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-01\" data-source=\"BDAG\" data-search=\"Κλαυδία, ας, ἡ nome próprio feminino Cláudia, cristã mencionada por Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κλαυδία, ας, ἡ</td><td>nome próprio feminino</td><td>Cláudia, cristã mencionada por Paulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-02\" data-source=\"BDAG\" data-search=\"Κλαύδιος, ου, ὁ nome próprio masculino Cláudio; imperador e outros portadores do nome BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κλαύδιος, ου, ὁ</td><td>nome próprio masculino</td><td>Cláudio; imperador e outros portadores do nome</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-03\" data-source=\"BDAG\" data-search=\"κλαυθμός, οῦ, ὁ substantivo masculino pranto; choro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλαυθμός, οῦ, ὁ</td><td>substantivo masculino</td><td>pranto; choro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-04\" data-source=\"BDAG\" data-search=\"κλάω verbo partir pão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλάω</td><td>verbo</td><td>partir pão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-05\" data-source=\"BDAG\" data-search=\"κλεῖθρον, ου, τό substantivo neutro tranca; ferrolho; barreira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλεῖθρον, ου, τό</td><td>substantivo neutro</td><td>tranca; ferrolho; barreira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-06\" data-source=\"BDAG\" data-search=\"κλείς, κλειδός, ἡ substantivo feminino chave literal ou figurada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλείς, κλειδός, ἡ</td><td>substantivo feminino</td><td>chave literal ou figurada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-07\" data-source=\"BDAG\" data-search=\"κλείω verbo fechar; trancar; impedir acesso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλείω</td><td>verbo</td><td>fechar; trancar; impedir acesso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-08\" data-source=\"BDAG\" data-search=\"κλέμμα, ατος, τό substantivo neutro furto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλέμμα, ατος, τό</td><td>substantivo neutro</td><td>furto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-09\" data-source=\"BDAG\" data-search=\"Κλεόβιος, ου nome próprio masculino Cleóbio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κλεόβιος, ου</td><td>nome próprio masculino</td><td>Cleóbio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-10\" data-source=\"BDAG\" data-search=\"Κλεοπᾶς, ᾶ, ὁ nome próprio masculino Cléopas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κλεοπᾶς, ᾶ, ὁ</td><td>nome próprio masculino</td><td>Cléopas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-11\" data-source=\"BDAG\" data-search=\"κλέος, ους, τό substantivo neutro fama; glória BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλέος, ους, τό</td><td>substantivo neutro</td><td>fama; glória</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-12\" data-source=\"BDAG\" data-search=\"κλέπτης, ου, ὁ substantivo masculino ladrão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλέπτης, ου, ὁ</td><td>substantivo masculino</td><td>ladrão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-13\" data-source=\"BDAG\" data-search=\"κλέπτω verbo furtar; roubar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλέπτω</td><td>verbo</td><td>furtar; roubar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-14\" data-source=\"BDAG\" data-search=\"κλῆμα, ατος, τό substantivo neutro ramo de videira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλῆμα, ατος, τό</td><td>substantivo neutro</td><td>ramo de videira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-15\" data-source=\"BDAG\" data-search=\"Κλήμης, εντος, ὁ nome próprio masculino Clemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κλήμης, εντος, ὁ</td><td>nome próprio masculino</td><td>Clemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-16\" data-source=\"BDAG\" data-search=\"κληρονομέω verbo herdar; obter; adquirir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κληρονομέω</td><td>verbo</td><td>herdar; obter; adquirir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-17\" data-source=\"BDAG\" data-search=\"κληρονομία, ας, ἡ substantivo feminino herança; propriedade; salvação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κληρονομία, ας, ἡ</td><td>substantivo feminino</td><td>herança; propriedade; salvação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-18\" data-source=\"BDAG\" data-search=\"κληρονόμος, ου, ὁ substantivo masculino herdeiro; beneficiário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κληρονόμος, ου, ὁ</td><td>substantivo masculino</td><td>herdeiro; beneficiário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-19\" data-source=\"BDAG\" data-search=\"κλῆρος, ου, ὁ substantivo masculino sorte; porção; destino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κλῆρος, ου, ὁ</td><td>substantivo masculino</td><td>sorte; porção; destino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0203-20\" data-source=\"BDAG\" data-search=\"κληρόω verbo sortear; receber; obter herança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κληρόω</td><td>verbo</td><td>sortear; receber; obter herança</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0203-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κλαυδία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κλαυδία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja, por exemplo, o índice de Sb): Cláudia, cristã mencionada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:21</a>.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κλαύδιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κλαύδιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (nome encontrado frequentemente): Cláudio. ① Tibério Cláudio Druso Nero Germânico, imperador romano (41–54 d.C.); suas medidas contra os judeus de Roma (Sueton., Claudius 25; Cass. Dio 60, 6; veja Schürer III 77f; Zahn, acerca de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>; ABludau, Der Katholik 83, 1903, 113ff; 193ff; Harnack, SBBerlAk 1912, 674ff; JJuster, Les Juifs dans l’empire romain 1914, II 171; 199; AWikenhauser, Die AG 1921, 323f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>. Uma fome durante seu reinado (Schürer I 457, 8; VWeber, D. antiochen. Kollekte 1917, 38f; Wikenhauser, obra citada 407ff; KGapp, The Universal Famine under Claudius: HTR 28, ’35, 258–65; Haenchen, comentário à passagem), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>.—HDessau, Gesch. d. röm. Kaiserzeit II 1, 1926; AMomigliano, Claudius 2 ’61; Pauly-W. III 2778ff; Kl. Pauly I 1215–18. ② Cláudio Lísias, funcionário romano em Jerusalém (<span class=\"greek\">χιλίαρχος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σπείρης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:31</a>; veja Schürer I 378), na época da prisão de Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:26</a>. ③ Cláudio Éfebo, cristão romano enviado a Corinto como representante da igreja de Roma, 1 Cl 65:1. ④ Cristão de Putéoli que ofereceu hospitalidade a Paulo, AcPl Ha 8, 1; 3; 7.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλαυθμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλαυθμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">κλαίω</span>; Hom. e outros; inscrições [Sb 7541, 15: II d.C.]; LXX; pseudepígrafos, Philo, Joseph., Just.): pranto, choro (com <span class=\"greek\">ὀδυρμός</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a> (Jer 38:15; <span class=\"greek\">θρῆνος</span>, encontrado com ambos aqui e também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a>, variante de leitura, ocorre ainda em TestJob 31:7; Philo, Vi. Cont. 73; e Jos., Ant. 20, 112, com <span class=\"greek\">κλαυθμός</span>). <span class=\"greek\">ἱκανὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">πάντων</span>, todos começaram a chorar intensamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:37</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., com <span class=\"greek\">ὁ</span> (o artigo indica o caráter singular e extremo da ação), <span class=\"greek\">βρυγμὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀδόντων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:12</a>; 13:42, 50; 22:13; 24:51; 25:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:28</a> (sobre essas passagens, veja BSchwanke, BZ 16, ’72, 121f).—DELG, s.v. <span class=\"greek\">κλαίω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλάω</span>, 1º aoristo <span class=\"greek\">ἔκλασα</span> (Hom.+; inscrições de Gaza: SEG VIII, 269, 6 [III/II a.C.]; PLips 39, 12; LXX, Philo; Jos., Bell. 5, 407, Vi. 212 e outras passagens): partir, em nossa literatura apenas no sentido de partir pão (cf. Jer 16:7; PGM 4, 1392f. Mas já em Anacr., Fgm. 69 Diehl 2 <span class=\"greek\">ἰτρίου</span> <span class=\"greek\">λεπτοῦ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">ἀποκλάς</span>. Também Diod S 17, 41, 7 <span class=\"greek\">οἱ</span> <span class=\"greek\">διακλώμενοι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄρτων</span> = aqueles pães que foram partidos.—A LXX também emprega <span class=\"greek\">διαθρύπτειν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἄρτον</span>: Is 58:7), ato pelo qual o chefe da família dava o sinal para iniciar a refeição (<span class=\"hebrew\">פָּתַת</span> <span class=\"hebrew\">לֶחֶם</span>, <span class=\"hebrew\">פָּרַס</span>). Essa era a prática de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:19</a>; 15:36; 26:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:6</a>, 19; 14:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:19</a>; 24:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:24</a>. Da mesma forma, acerca das refeições cultuais dos primeiros cristãos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:46</a>; 20:7, 11; 27:35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:16</a>; D 14:1; IEph 20:2; AcPl Ha 4, 4.—Bibliografia sob <span class=\"greek\">κλάσις</span>.—B. 563. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλεῖθρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλεῖθρον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κλείω</span> e o verbete seguinte; X., Pla. e outros; Sb 6253, 9 [137 a.C.]; PGM 4, 2261; 2294; LXX; ApcEsdr 5:13 p. 30, 12 Tdf. <span class=\"greek\">τὰ</span> <span class=\"greek\">κλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυλῶνος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικός</span>; SibOr 2, 228): literalmente, tranca ou ferrolho usado para fechar uma porta; figuradamente, barreira, acerca da costa como barreira para o mar, 1 Cl 20:6 (Appian, Mithr. 24 §96, sobre as ‘trancas’ com que se fechava um porto marítimo ameaçado).—B. 467. DELG s.v. <span class=\"greek\">κλείς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλείς, κλειδός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλείς</span>, <span class=\"greek\">κλειδός</span>, <span class=\"greek\">ἡ</span> (cf. latim ‘clavis’ = chave; Hom. e outros; inscrições, papiros, LXX; ParJer 4:4 <span class=\"greek\">κλεῖδας</span> [<span class=\"greek\">κλεῖς</span> no códice C]; empréstimo no rabínico; Just., D. 17, 4 [referência a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:13</a>]), acusativo <span class=\"greek\">κλεῖδα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:52</a> (POxy 113, 3; LXX [Thackeray 150]), e <span class=\"greek\">κλεῖν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:7</a>; 20:1 (em ambos, <span class=\"greek\">κλεῖδα</span> como variante de leitura; SIG 996, 24; POxy 1127, 25); plural <span class=\"greek\">κλεῖδας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:19</a>; 1 Cl 43:3 (OGI 229, 96 e 98; PHerm 8 II, 5; BGU 253, 18), e <span class=\"greek\">κλεῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:19</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:18</a> (Ctesias [IV a.C.]: 688 Fgm. 13, 16 Jac. = Persians 14 <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κλεῖς</span> <span class=\"greek\">πάσας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλείων</span> <span class=\"greek\">εἶχε</span>; POxy 729, 23 [137 d.C.]; BGU 75, 13; Just., D. 17, 4.—B-D-F § 47, 3; W-S. §9, 7; Mlt-H. 131f; Mayser 272 [bibliografia]; Reinhold 51). ① Algo usado para trancar, chave, literalmente: <span class=\"greek\">σφραγίζειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κ</span>., 1 Cl 43:3 (inscrição [218 a.C.]: <span class=\"greek\">ΕΛΛΗΝΙΚΑ</span> 7, ’34 p. 179, 9f <span class=\"greek\">κλεῖδας</span> <span class=\"greek\">ἐχέτωσαν</span>, … <span class=\"greek\">σφραγιζέσθωσαν</span>).—As expressões seguintes aproximam-se do sentido figurado: <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ᾅδου</span> (<span class=\"greek\">ᾅδης</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:18</a> (cf. IKourion 127, 53 = IDefixAudollent 22). <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀβύσσου</span>, 20:1, ou <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">φρέατος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀβύσσου</span>, 9:1 (<span class=\"greek\">ἄβυσσος</span> 2; sobre a chave do mundo inferior, veja Paus. 5, 20, 3; PGM 4, 341–42; New Docs 1, nº 8 linha 3 e p. 5: ‘a noção de Anúbis como guardião das chaves do Hades [nº 8, 3] é um elemento habitual dos encantamentos mágicos’). Igualmente, a representação de Pedro como guardião da porta do céu: <span class=\"greek\">δώσω</span> <span class=\"greek\">σοι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κλεῖδας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:19</a> (cf. Ctesias acima; veja JGrill, D. Primat des Petrus 1904; WKöhler, ARW 8, 1905, 214ff [bibliografia]; ADell, ZNW 15, 1914, 27ff, esp. 33ff; VBurch, JBL 52, ’33, 147–52; HvCampenhausen, D. Schlüsselgewalt der Kirche: EvTh 4, ’37, 143–69. Veja também <span class=\"greek\">πέτρα</span> 1b e o fim de <span class=\"greek\">Πέτρος</span>). <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Δαυίδ</span> (cf. Is 22:22, variante de leitura <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οἴκου</span> <span class=\"greek\">Δ</span>.), possuir a chave de Davi, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:7</a> (GMinestrina, Bibbia e oriente 20, ’78, 182; sobre a autoridade sobre as chaves, cf. Parmenides 1, 14 <span class=\"greek\">Δίκη</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">κληῖδας</span>, isto é, da porta que conduz ao domínio da luz e do conhecimento; OGI 229, 56 [III a.C.] <span class=\"greek\">κυριεύσοντα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κλειδῶν</span>; igualmente Polyb. 4, 18, 2. A expressão <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κλεῖς</span> = possuir as chaves, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:18</a>; cf. 3:7; 20:1, já aparece em Pind., P. 8, 4). ② Meio de obter acesso a algo, chave, figuradamente (sobre outros tipos de uso figurado, veja Diod S 2, 8, 3 <span class=\"greek\">καθαπερεὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κλεῖς</span> <span class=\"greek\">ἔχειν</span> = possuir as chaves, por assim dizer; Artem. 3, 54 <span class=\"greek\">κλείς</span> é símbolo de <span class=\"greek\">πίστις</span> = confiança): <span class=\"greek\">αἴρειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κλεῖδα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span>, retirar a chave (da porta) do conhecimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:52</a>; cf. aqui o fragmento muito danificado de evangelho apócrifo POxy 655, 41–46 (A Syn. 194, 135) e a restauração [<span class=\"greek\">τὴν</span> <span class=\"greek\">κλεῖδα</span>] <span class=\"greek\">τῆς</span> [<span class=\"greek\">γνώσεως</span>]. AHultgren, Forum 7, 91, 165–82.—B. 468f. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλείω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλείω</span>, futuro <span class=\"greek\">κλείσω</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:7</a>; 1º aoristo <span class=\"greek\">ἔκλεισα</span>; 3ª pessoa do plural do perfeito <span class=\"greek\">κεκλείκασιν</span>, 1 Km 23:20; imperativo médio aoristo <span class=\"greek\">κλεῖσαι</span> (ApcMos 12). Na passiva: 1º aoristo <span class=\"greek\">ἐκλείσθην</span>; perfeito <span class=\"greek\">κέκλεισμαι</span>, 3ª pessoa do plural <span class=\"greek\">κέκλεινται</span>, Sus 20 Theod., particípio <span class=\"greek\">κεκλεισμένος</span> (veja <span class=\"greek\">κλεῖς</span>; Hom. e outros; inscrições, papiros, LXX, JosAs, GrBar, Joseph.). ① Impedir a passagem por uma abertura, fechar, trancar, barrar. ⓐ Literalmente, <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span> (Aristophon Com. [IV a.C.] 7 ed. Kock II p. 278; Herodas 6, 98; Epict. 3, 22, 14; 2 Ch 28:24; JosAs 5:9), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:8</a>. Na passiva (Menand., Epitr. 1076 S. [718 Kö.]; Jos., Ant. 18, 74; cf. X., Cyr. 7, 5, 27; JosAs 10:6; 14:5; GrBar 17:1; Did., Gen. 192, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:19</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:30</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πυλῶνες</span>, os portões (da Jerusalém celestial; cf. Is 60:11), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:25</a>.—Sobre construções, fechar, trancar (BGU 1116, 15 [13 a.C.]; Is 24:10): <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">σκηνήν</span>, fechar o tabernáculo, 1 Cl 43:3. Na passiva, <span class=\"greek\">δεσμωτήριον</span> … <span class=\"greek\">κεκλεισμένον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:23</a>. Encerrar (alguém) dentro: [<span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἐ</span>]<span class=\"greek\">κ</span>[<span class=\"greek\">έ</span>]<span class=\"greek\">κλιστο</span>, AcPl Ha 2, 6; [<span class=\"greek\">οἱ</span> <span class=\"greek\">κ</span>]<span class=\"greek\">εκλισμένοι</span>, 3, 19.—Uso absoluto, fechar (Jos., Vi. 153), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:7a</a>b (cf. Is 22:22, variante de leitura); 20:3. ⓑ Figuradamente, <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span>, fechar os céus para que não chova, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a>; na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>. Numa visão, <span class=\"greek\">ἐκλείσθησαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">οὐρανοί</span>, os céus foram fechados, Hv 1, 2, 1. <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span>, fechar o reino dos céus, isto é, impedir as pessoas de entrar nele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:13</a> (MBlack, An Aramaic Approach 3, ’67, 259–61 [siríaco sinaítico]). ② <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, fechar o coração a alguém, expressão idiomática, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JO.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:17</a> (cf. figura semelhante <span class=\"greek\">στόμα</span> <span class=\"greek\">κεκλεισμένον</span>, Sir 30:18).—B. 847f. DELG s.v. <span class=\"greek\">κλείς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλέμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλέμμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">κλέπτω</span>): ato de roubar, furto (assim, indicando uma ação, Eur. e outros.—Na LXX, somente ‘bens roubados’), <span class=\"greek\">μετανοεῖν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κλεμμάτων</span>, arrepender-se dos furtos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:21</a>. Numa lista de vícios, Hm 8:5; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:22</a> D.—DELG s.v. <span class=\"greek\">κλέπτω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κλεόβιος, ου</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κλεόβιος</span>, <span class=\"greek\">ου</span> (Suda K 1717 [<span class=\"greek\">ὄνομα</span> <span class=\"greek\">ἱερέως</span> <span class=\"greek\">εἰδώλων</span>]; veja também AcPt 3 [Aa I 48, 6]): Cleóbio, gnóstico em Corinto, AcPlCor 1:2 (talvez o mesmo mencionado em Eus., HE 4, 22, 5); AcPl Ha 6, 28.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κλεοπᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κλεοπᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (também <span class=\"greek\">Κλεόπας</span>, em edições): Cléopas (O. Wilck II, 1438; 1442; 1448 [todos do II d.C.]; forma abreviada de <span class=\"greek\">Κλεόπατρος</span>). Esse nome genuinamente grego, que evidentemente ocupa o lugar do semítico <span class=\"greek\">Κλωπᾶς</span> (veja esse verbete), sem necessariamente indicar que as duas pessoas assim designadas nos Evangelhos sejam idênticas, é usado por um discípulo de Jerusalém sobre quem não há outras informações, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:18</a>. (Veja B-D-F § 53, 2d; 125, 2; Dssm., B 184, 6 [BS 315, 2]; Dalman, Gramm. 2 179, 4; Mlt-H. p. 88.)—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλέος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλέος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e outros; papiros; Job 28:22; 30:8; Philo; Jos., Ant. 4, 105; 115; 19, 223; SibOr 3, 431; 5, 428): fama, glória; <span class=\"greek\">τὸ</span> <span class=\"greek\">γενναῖον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">κ</span>., 1 Cl 5:6. <span class=\"greek\">κ</span>. <span class=\"greek\">περιποιεῖσθαι</span> <span class=\"greek\">ἑαυτῷ</span>, conquistar fama para si, 54:3. <span class=\"greek\">ποῖον</span> <span class=\"greek\">κ</span>., seguido de <span class=\"greek\">εἰ</span>, que mérito há se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:20</a>.—DELG. M-M. TW. SV.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλέπτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλέπτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja o verbete seguinte; Hom. e outros; papiros, LXX; TestSol 10:38 C; TestAbr A 10 p. 88, 2 [Stone p. 24]; JosAs cap. 13 códice A [p. 57, 24 Bat.]; Philo; Jos., Ant. 16, 3; Ar.; Just., D. 12, 3): ladrão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19f</a>; 24:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:33</a>, 39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:1</a> (com <span class=\"greek\">λῃστής</span>, como no versículo 8 e em EpJer 57. Em oposição a <span class=\"greek\">ποιμήν</span>, como em Il. 3, 11; Maximus Tyr. 19, 4e), 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:15</a>; 1 Cl 35:8 (Ps 49:18). Excluído do reino de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:10</a>. De Judas, o delator, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:6</a>. A invasão praticada por um ladrão como figura de algo repentino, surpreendente, inesperado; usada a respeito da Parúsia (como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:39</a> acima): <span class=\"greek\">ὡς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">νυκτὶ</span> <span class=\"greek\">ἔρχεσθαι</span>, vir como ladrão de noite, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:2</a> (o ladrão noturno: Dio Chrys. 52 [69], 8; Job 24:14; Philo, Spec. Leg. 4, 10); cf. versículo 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:3</a>; 16:15.—GFörster, ZNW 17, 1916, 169–77; WHarnisch, Eschatologische Existenz, ’73: excursus II, 84–116.—Na declaração sobre os pastores, os líderes religiosos que vieram antes de Jesus são chamados figuradamente de ladrões, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:8</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλέπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλέπτω</span>, futuro <span class=\"greek\">κλέψω</span>; 1º aoristo <span class=\"greek\">ἔκλεψα</span>. Na passiva: 2º aoristo <span class=\"greek\">ἐκλάπην</span>; particípio perfeito <span class=\"greek\">κεκλεμμένον</span>, Gen. 30:33; Dg 2:2 (veja o verbete anterior; Hom.+): furtar, roubar <span class=\"greek\">τὶ</span>, alguma coisa; <span class=\"greek\">τοὺς</span> <span class=\"greek\">γάμους</span>, consumar o casamento secretamente, isto é, sem a bênção da comunidade, GJs 15:2, 4. Na passiva, Dg 2:2, 7 (sobre sacrilégio por furto, veja Juvenal, Satires 13, 147–52; outras referências em EBlakeney, The Epistle to Diognetus ’43, 36f). <span class=\"greek\">τινά</span>, alguém, acerca de pessoa morta (Chariton 3, 2, 7; 2 Km 21:12; Tob 1:18 BA); acerca de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:64</a>; 28:13; GPt 8:30. Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:19f</a>; 19:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:9</a>; D 2:2 (os últimos cinco, Ex 20:14.—Em Epict. 3, 7, 12, o mandamento assume a forma <span class=\"greek\">μὴ</span> <span class=\"greek\">κλέπτετε</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:28</a>.—B. 789. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλῆμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλῆμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span>: ramo, sobretudo da videira (Aristoph. e outros; Pla., Rep. 1, 353a <span class=\"greek\">ἀμπέλου</span> <span class=\"greek\">κλῆμα</span>; Theophr., HP 4, 13, 5; Pollux 1, 237 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀμπέλου</span> [isto é, <span class=\"greek\">κλάδος</span>] <span class=\"greek\">κλῆμα</span>; PFlor 148, 9; LXX; GrBar; ApcSed 8:3 p. 132, 38 Ja; Jos., Ant. 2, 64; 12, 75 <span class=\"greek\">κ</span>. <span class=\"greek\">ἀμπέλων</span>; SibOr 7, 148), na declaração sobre a videira e os ramos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:2</a>, 4–6 (ESchweitzer, em volume memorial de TWManson ’59, 230–45).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κλήμης, εντος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κλήμης</span>, <span class=\"greek\">εντος</span>, <span class=\"greek\">ὁ</span>: Clemente (a forma grega desse nome latino [Clemens] ocorre, por exemplo, em Philostrat., Vi. Soph. 2, 27, 2; Jos., Ant. 19, 37–47; OGI 207, 1; 574, 9; POxy 241, 1; 340; Sb 4613; 8089, 1 [início do II d.C.]). ① Membro da igreja em Filipos, honrado por Paulo com o título ‘cooperador’ (um Clemente de Filipos é mencionado em CIL III 633), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a>. ② Membro da igreja em Roma, encarregado das relações com outras igrejas, Hv 2, 4, 3; às vezes identificado com 1, embora sem razões suficientes. A pessoa em questão é certamente o autor de 1 Cl; é mencionada na subscrição dessa carta, também na subscrição de 2 Cl, e a tradição desde meados do segundo século o reconhece como terceiro bispo de Roma.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κληρονομέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κληρονομέω</span>, futuro <span class=\"greek\">κληρονομήσω</span>; 1º aoristo <span class=\"greek\">ἐκληρονόμησα</span>; perfeito <span class=\"greek\">κεκληρονόμηκα</span> (veja os quatro verbetes seguintes; Demosth. e outros; inscrições, papiros, LXX, En; TestSol 9:5; TestJob; TestNapht 5:8; Philo, Joseph.; Just.). ① Ser herdeiro, herdar. ⓐ Em uso absoluto, herdar, ser herdeiro (Epict. 3, 2, 8; SIG 833, 8; Sb 4638, 12 [II a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:30</a> (Gen 21:10); B 13:1. Jesus como <span class=\"greek\">ὁ</span> <span class=\"greek\">κληρονομῶν</span>, o herdeiro, 14:5. ⓑ Com objeto pessoal, o verbo significa suceder alguém como herdeiro, ser herdeiro de alguém (Posidon.: 87 Fgm. 36 p. 243, 32f Jac.; POxy 1067, 8; PRyl 28, 226 <span class=\"greek\">δοῦλος</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κληρονομήσει</span>; Gen 15:3, acerca de Eliezer como herdeiro de Abraão; Pr 13:22; Tob 3:15; Jos., Ant. 20, 241; em tom sarcástico, Sir 19:3), 1 Cl 16:13 (Is 53:12). ② Adquirir, obter, entrar na posse de <span class=\"greek\">τὶ</span>, alguma coisa (grego helenístico [Phryn. 129 Lob.; Moeris 149]; cf. Polyb. 18, 38, 8 <span class=\"greek\">φήμην</span>; 15, 22, 3; Lucian, Dial. Mort. 11, 3; BGU 19 II, 1; 1024 VIII 16; PRyl 117, 13; LXX; TestSol 9:5; TestJob 18:6; Philo, Rer. Div. Her. 98 <span class=\"greek\">σοφίαν</span>), especialmente da participação na salvação messiânica: <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (Ps 24:13; 36:9, 11, 22; En 5:6; 7; cf. Iren. 5, 9, 4 [Harv. II 344]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:5</a>; D 3:7. <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">θεοῦ</span>, o reino de Deus (cf. 1 Macc 2:57), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9f</a> (= Pol 5:3); 15:50a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:21</a>; IEph 16:1; IPhld 3:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:34</a>. <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span>, receber, participar da vida eterna (cf. SibOr Fgm. 3, 47), 19:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:25</a>; 18:18; Hv 3, 8, 4. <span class=\"greek\">δόξαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τιμήν</span>, 1 Cl 45:8. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανῷ</span> <span class=\"greek\">πνευματικὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄφθαρτον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">κ</span>., final de Mk no manuscrito Freer, 10ff. <span class=\"greek\">σωτηρίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:14</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπαγγελίας</span> (PsSol 12:6), o que foi prometido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:12</a>; 1 Cl 10:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀφθαρσίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.50\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:50b</a> (cf. Just., D. 139, 5). (<span class=\"greek\">τὴν</span>) <span class=\"greek\">εὐλογίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:9</a>. <span class=\"greek\">διαφορώτερον</span> <span class=\"greek\">ὄνομα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:4</a> (= 1 Cl 36:2.—<span class=\"greek\">κλ</span>. <span class=\"greek\">ὄνομα</span>, como em Dionys. Byz. §7; Themist., Paraphrases Aristot. II p. 172, 13 Spengel [1866]). <span class=\"greek\">ταῦτα</span>, tudo isso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:7</a> (veja New Docs 5, 35).—DELG s.v. <span class=\"greek\">κλῆρος</span> e <span class=\"greek\">νέμω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κληρονομία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κληρονομία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete anterior; Isocr., Demosth. e outros; inscrições, papiros, LXX; En 99:14; TestJob, TestBenj, JosAs, Philo; Jos., Bell. 2, 249; Just.; Tat. 3, 3; Mel.). ① Herança (assim quase sempre na literatura geral; também Num 26:54, 56.—Figuradamente, <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐκβάλωσι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">κ</span>. [daqueles que negam a natureza humana de Cristo], Iren. 3, 22, 1 [Harv. II 121, 7]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:14</a>; Hv 3, 12, 2; Hs 5, 6, 4. <span class=\"greek\">μερίσασθαι</span> <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>., dividir a herança com alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:13</a>. <span class=\"greek\">λαὸς</span> <span class=\"greek\">κληρονομίας</span>, povo da herança, B 14:4. Em seu retorno, o Amado virá à sua herança, 4:3. ② Posse, propriedade (Sir 22:23; 24:20; Jdth 16:21; 1 Macc 2:56; 6:24): <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">κληρονομίαν</span>, dar uma propriedade a alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:5</a>; 13:33 D; 1 Cl 36:4 (os dois últimos, Ps 2:8). <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>., receber algo como posse (cf. Aristot., EN 7, 14 p. 1153b, 33; TestBenj 10:4 f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>. <span class=\"greek\">σχοίνισμα</span> <span class=\"greek\">κληρονομίας</span> <span class=\"greek\">αὐτοῦ</span>, porção hereditária de Yahweh, isto é, Israel, 1 Cl 29:2 (Dt 32:9). ③ Comum no uso cristão (correspondente à LXX), (posse da) salvação transcendente (como herança dos filhos de Deus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:18</a>. <span class=\"greek\">ἀπολαμβάνειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνταπόδοσιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., receber a herança como recompensa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:24</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπαγγελία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰωνίου</span> <span class=\"greek\">κ</span>., a promessa da herança eterna, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>. <span class=\"greek\">ἐσφάλησαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰωνίας</span> (<span class=\"greek\">αἰωνίου</span> Ox 1602, 27–29 = AcPl BMM recto, 26–27), AcPl Ha 8, 21 (acerca dos judeus como povo de Deus). <span class=\"greek\">κ</span>. <span class=\"greek\">ἄφθαρτος</span>, uma posse imperecível, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:4</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, nossa salvação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:14</a>, concedida por Deus, versículo 18. <span class=\"greek\">δοῦναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἡγιασμένοις</span>, conceder salvação entre os consagrados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:32</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">βασιλείᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, ter parte no reino de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:5</a> (cf. Just., D. 122, 6; e veja PHammer, JBL 79, ’60, 267–72). ④ Abstrato em lugar do concreto = os herdeiros (cf. <span class=\"greek\">ἀκροβυστία</span> 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:1</a>, variante de leitura.—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κληρονόμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κληρονόμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja os dois verbetes anteriores; Pla.+; inscrições, papiros, LXX; PsSol 8:11; Philo; Jos., Ant. 13, 322; Tat. 25, 2), geralmente ‘herdeiro’. ① Aquele que é designado herdeiro, herdeiro (Appian, Bell. Civ. 3, 11 §36 <span class=\"greek\">υἱὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a>; Hs 5, 2, 6. ② Aquele que recebe algo como posse, beneficiário, extensão figurada da acepção 1: em nossa literatura, acerca de Deus como aquele que concede (cf. Hs 5, 2, 6; ApcSed 6:2). ⓐ De Cristo, <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">ἔθηκεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντων</span>, a quem Deus constituiu herdeiro de todas as coisas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:2</a> (cf. Did., Gen. 41, 23 <span class=\"greek\">οὐ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὕστερον</span> <span class=\"greek\">πεποίηκεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κληρονόμον</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ὄντα</span> <span class=\"greek\">ἐφανέρωσεν</span> = pois [o Pai] não o fez [o Salvador] herdeiro posteriormente, mas o revelou como aquele que já era herdeiro). ⓑ Dos fiéis; como <span class=\"greek\">τέκνα</span>, são: <span class=\"greek\">κληρονόμοι</span>, <span class=\"greek\">κληρονόμοι</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:7</a>. Mais especificamente, <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">διαθήκης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, em que <span class=\"greek\">διαθήκη</span> (veja esse verbete, 2) oscila entre ‘última vontade e testamento’ e ‘decreto’, B 6:19; 13:6. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐπαγγελίαν</span> <span class=\"greek\">κληρονόμοι</span>, herdeiros segundo a promessa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:29</a> (sobre a imagem, veja Straub 96f); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:17</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span>, herdeiros do reino, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:5</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">κληρονόμοι</span> <span class=\"greek\">γενηθῶμεν</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐλπίδα</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">αἰωνίου</span>, para que nos tornássemos herdeiros segundo a esperança da vida eterna, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:7</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">κ</span>., ele (Noé) tornou-se herdeiro da justiça que vem pela fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a> (sobre o genitivo do substantivo abstrato, cf. Demosth. 22, 34 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀτιμίας</span>). Abraão e todos os que esperam a ‘justiça da fé’, como ele esperava, são <span class=\"greek\">κ</span>. <span class=\"greek\">κόσμου</span>, em contraste com os que dependem da lei, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:13f</a> (cf. Philo, Somn. 1, 175 <span class=\"greek\">τῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">κληρονόμον</span> <span class=\"greek\">μερῶν</span>).—Acerca da herança em Paulo, especialmente em Gal, veja MConrat, ZNW 5, 1904, 204–27; OEger, ibid. 18, 1918, 84–108; WCalder, JTS 31, 1930, 372–74.—B. 779. DELG s.v. <span class=\"greek\">κλῆρος</span> e <span class=\"greek\">νέμω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κλῆρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κλῆρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; empréstimo no rabínico). ① Objeto especialmente marcado, como pedrinha, fragmento de cerâmica ou vareta, usado para decidir algo, sorte (Diod S 13, 34, 6 <span class=\"greek\">κλήρῳ</span> = por sorteio): <span class=\"greek\">βάλλειν</span> <span class=\"greek\">κ</span>. (<span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>), lançar sortes (sobre alguma coisa), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JOH.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24</a>; B 6:6 (Ps 21:19. A expressão como tal ocorre muitas vezes na LXX, também em Jos., Ant. 6, 61; escólio sobre Soph., Antig. 275 p. 232 Papag.; cf. 1QS 6, 16–22). <span class=\"greek\">ἔπεσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, a sorte recaiu sobre alguém (Jon 1:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:26b</a>. <span class=\"greek\">ἀνέβη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Συμεών</span>, GJs 24:4. <span class=\"greek\">ἔδωκαν</span> <span class=\"greek\">κλήρους</span> <span class=\"greek\">αὐτοῖς</span>, deram-lhes (aos candidatos) sortes, versículo 26a. Sobre isso, LThornton, JTS 46, ’45, 51–59; JLindblom, VetusT 12, ’62, 164–78 (contexto veterotestamentário); WBeardslee, NovT 4, ’60, 245–52 (Qumran). ② Aquilo que é atribuído por sorteio ou simplesmente concedido como porção ou parte, porção, parte (Pla.; Diod S 40, 3, 7, em conexão com a distribuição do país conquistado pelos judeus; JosAs 10:1, Potifar e sua família vão à propriedade deles; ApcMos 22 <span class=\"greek\">τὰ</span> <span class=\"greek\">φυτὰ</span> … <span class=\"greek\">τοῦ</span> <span class=\"greek\">κλήρου</span>; Mitt-Wilck. I/1, pp. 280–83; Jos., Bell. 2, 83), sobretudo aquilo que cabe a alguém pela graça divina (Ael. Aristid. 30, 23 K. = 10 p. 123 D.; Hierocles 4, 426 <span class=\"greek\">ἀθάνατος</span> <span class=\"greek\">κ</span>. = porção eterna concedida pelos deuses; LXX): <span class=\"greek\">λαγχάνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">διακονίας</span> <span class=\"greek\">ταύτης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:17</a> (cf. <span class=\"greek\">κλῆρον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπισκοπῆς</span> <span class=\"greek\">ἔχειν</span>, Iren. 1, 27, 1 [Harv. I 215, 1]); cf. versículo 25, variante de leitura. <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἡγιασμένοις</span>, receber um lugar entre o povo santo de Deus, 26:18 (cf. Wsd 5:5 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγίοις</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτοῦ</span>). <span class=\"greek\">μερίς</span> e <span class=\"greek\">κλῆρος</span> juntos (escólio sobre Apollon. Rhod. 1, 1082a; Dt 10:9; 12:12 e outras passagens; Is 57:6): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">μερὶς</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τούτῳ</span>, não tens parte nem quinhão neste assunto, 8:21. <span class=\"greek\">μερὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτί</span>, participação na herança do povo de Deus na (esfera da) luz, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:12</a> (cf. 1QH 11, 11f). <span class=\"greek\">καὶ</span> <span class=\"greek\">κλῆρον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μερισμὸν</span> <span class=\"greek\">λαμβάνοντες</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, recebendo uma porção e parte por meio do espírito de Cristo, AcPl Ha 8, 18//Ox 1602, 22f = BMM recto 23f (acerca de profetas). <span class=\"greek\">κ</span>. <span class=\"greek\">Ἐφεσίων</span>, a classe dos efésios, IEph 11:2.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:3</a>, os <span class=\"greek\">κλῆροι</span> parecem designar o ‘rebanho’ como um todo, isto é, as várias partes do povo de Deus confiadas como ‘porções’ a presbíteros ou pastores individuais (sobre diversas porções que juntas formam um todo: Simplicius, em Epict. p. 71, 10, onde os <span class=\"greek\">κλῆροι</span> do bem e do mal [segundo a doutrina dos que presumem dois princípios originários] são diferenciados <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀϊδίου</span> [eternamente]). Cf. Goppelt, KEK, comentário à passagem. ③ Aquilo que inevitavelmente acontece, sorte, destino, especialmente de mártires: <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπαρτίζειν</span>, cumprir o próprio destino, MPol 6:2; cf. ITr 12:3; IRo 1:2; IPhld 5:1.—Pauly-W., XI 810ff; XIII 1451–1504; Kl. Pauly III 252.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0203-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κληρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κληρόω</span>, aoristo médio <span class=\"greek\">ἐκληρωσάμην</span> (GJs 19:1, códices); perfeito médio, 2ª pessoa do singular <span class=\"greek\">κεκλήρωσαι</span> (GJs 9:1); particípio perfeito <span class=\"greek\">κεκληρωμένος</span> (MPol 6:2); 1º aoristo passivo <span class=\"greek\">ἐκληρώθην</span> (veja <span class=\"greek\">κλῆρος</span> e os três verbetes anteriores; Pind., Hdt.+; inscrições, papiros, LXX; TestIss 5:7; Philo; SibOr 5, 322). ① Designar por sorteio (na ativa, Diod S 15, 18, 3 <span class=\"greek\">κληρώσαντες</span>); na passiva, ser designado por sorteio (Appian, Mithrid. 102 §471 <span class=\"greek\">τοὺς</span> <span class=\"greek\">κληρουμένους</span> = os escolhidos por sorteio), em geral: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ἐκληρώθη</span>, conforme a sorte de cada um foi lançada, Dg 5:4. Se <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εἶναι</span> … em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:12</a> depender de <span class=\"greek\">ἐκληρώθημεν</span> do versículo 11, o sentido de <span class=\"greek\">κ</span>. no versículo 11 poderia ser ‘escolhidos’ (cf. PIand 27, 4 <span class=\"greek\">ἐκληρώθημεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">γεωργίαν</span>; BGU 625, 5 <span class=\"greek\">ἐκληρώθην</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">βουκόλια</span>). Mas alguns traduzem <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐκληρώθημεν</span> por ‘em quem nossa sorte foi lançada’ = ‘em quem temos nosso destino’, sugerindo envolvimento total na sorte de Cristo. Veja 2 abaixo. ② Obter por sorteio, na voz média; também simplesmente receber, ter <span class=\"greek\">τὶ</span>, alguma coisa (desde Eur., Tro. 29; Herm. Wr. 16, 14; Philo, Mos. 2, 101 e outras passagens; Sb 7031, 23 [72 d.C.]; 7032, 22): <span class=\"greek\">ὁ</span> <span class=\"greek\">κεκληρωμένος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">ὄνομα</span>, aquele que tinha o mesmo nome, MPol 6:2. <span class=\"greek\">τινὰ</span>, alguém: <span class=\"greek\">κεκλήρωσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρθένον</span>, recebeste a jovem por sorteio (para que a protejas), GJs 9:1. Com duplo acusativo: <span class=\"greek\">ἐκληρωσάμην</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">γυναῖκα</span>, 19:1 (códices). Na passiva: <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐκληρώθημεν</span>, ‘em quem obtivemos uma herança’, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:11</a>, parece ser a tradução mais provável dessa forma passiva, sendo a questão central que as nações também estão incluídas; mas veja 1 acima.—DELG s.v. <span class=\"greek\">κλῆρος</span>. M-M. TW.</p></section></article>"};
